import socket, string, sys, time

HOST, PORT = "challenge", 1337


def run_once(payload_bytes, total_wait=1.2):
    """Return (banner, after, closed)."""
    s = socket.create_connection((HOST, PORT), timeout=5)
    s.settimeout(0.5)
    banner = b""
    t0 = time.time()
    while time.time() - t0 < 3:
        try:
            d = s.recv(4096)
        except socket.timeout:
            break
        if not d:
            break
        banner += d
        if b"input: " in banner:
            break
    try:
        s.sendall(payload_bytes)
    except Exception:
        pass
    after = b""
    t0 = time.time()
    closed = False
    while time.time() - t0 < total_wait:
        try:
            d = s.recv(4096)
        except socket.timeout:
            continue
        except Exception:
            closed = True
            break
        if not d:
            closed = True
            break
        after += d
    try:
        s.close()
    except Exception:
        pass
    return banner, after, closed


def charset_map():
    print("### CHARSET MAP (payload = b'g' + c + b'g') ; DENIED => char NOT whitelisted")
    allowed, denied = [], []
    for code in list(range(0x20, 0x7f)) + [0x09, 0x0b, 0x0c, 0x7f]:
