    print("\nALLOWED (accepted or no-Denied) codes: %s" % "".join(chr(c) for c in allowed))
    print("ALLOWED repr: %r" % "".join(chr(c) for c in allowed))
    print("DENIED codes: %s" % "".join(chr(c) for c in denied))
    print("DENIED repr: %r" % "".join(chr(c) for c in denied))


def result_echo_probes():
