"""Third-stage probe: truthy-result payloads (in case remote branches on the result), edge cases, protocol quirks."""
import socket, time, sys

HOST, PORT = "challenge", 1337


def run(payload=None, shutdown_write=False, wait=1.5, read_banner=True):
    s = socket.create_connection((HOST, PORT), timeout=5)
    s.settimeout(0.5)
    banner = b""
    t0 = time.time()
    if read_banner:
        while time.time() - t0 < 3:
            try:
                d = s.recv(4096)
            except socket.timeout:
                break
            except Exception:
                break
            if not d:
                break
            banner += d
            if b"input: " in banner:
                break
    if payload is not None:
        try:
            s.sendall(payload)
        except Exception as e:
            pass
    if shutdown_write:
        try:
            s.shutdown(socket.SHUT_WR)
        except Exception:
            pass
    after = b""
    t0 = time.time()
    closed = False
    while time.time() - t0 < wait:
        try:
            d = s.recv(65536)
        except socket.timeout:
            continue
        except Exception:
            closed = True
            break
        if not d:
            closed = True
            break
        after += d
    t = time.time() - t0
    try:
        s.close()
    except Exception:
        pass
    return banner, after, closed, t


CASES = [
    # name, payload
    ("truthy_set      ", b'"{()}"\n'),
    ("truthy_dict     ", b'"{():()}"\n'),
    ("truthy_set_plus ", b'"{()}"+"{()}"\n'),           # inner returns "{()}{()}" -> outer SyntaxError-ish
    ("fstring_set     ", b'f"{()}"\n'),
    ("fstring_fmt     ", b'f"{():>40}"\n'),             # result string would contain spaces if anything printed it
    ("fstring_fmt2    ", b'f"{():{()}}"+\n'),           # junk, syntax error inside f-string
    ("empty_expr      ", b'""\n'),
    ("only_ws_like    ", b'\n'),
    ("flaglike_input  ", b'gctf{"*+*(=>:/)*+*"}\n'),
    ("nested_deep     ", b'(' * 200 + b')' * 200 + b'\n'),
    ("big_mult        ", b'"g"*(("g"=="g")+("g"=="g"))\n'),
    ("cmp_set         ", b'({()}>{()})\n'),
    ("walrus_set      ", b'(g:={()})\n'),
    ("dict_of_set     ", b'{{}:{}}\n'),
    ("double_star     ", b'{**{}}\n'),
    ("div             ", b'"gg"/(("g"=="g")+("g"=="g"))\n'),
]

print("### TRUTHY / EDGE-CASE PAYLOADS")
for name, payload in CASES:
    try:
        banner, after, closed, t = run(payload)
        print("  %s payload=%-28r after=%-46r closed=%-5s wait=%.2fs banner_ok=%s"
              % (name, payload, after, closed, t, banner.endswith(b"input: ")))
    except Exception as e:
        print("  %s payload=%-28r ERROR %r" % (name, payload, e))

print("\n### PROTOCOL EDGE CASES")
tests = [
    ("two lines       ", b'g\n"g"\n', False),
    ("no trailing NL  ", b'g', False),
    ("eof after prompt", b'', True),
    ("invalid utf8    ", b'\xff\xfe\n', False),
    ("nul byte        ", b'g\x00g\n', False),
    ("crlf            ", b'g\r\n', False),
    ("len 40000 ok    ", b'"' + b'g' * 39998 + b'"\n', False),
    ("len 40002 over  ", b'"' + b'g' * 40000 + b'"\n', False),
]
for name, payload, sh in tests:
    try:
