"""Independent builder: whitelist-only inner expression whose eval() yields an arbitrary outer program.

Inner alphabet: g c t f { " * + ( = > : / ) }
Atoms: ("g">"c") -> True(1); doubling chain gives 1,2,4,8,16,32,64 under names g,c,t,f,gg,cc,tt.
f"{n:c}" -> chr(n)  =>  the inner eval can emit ANY character, so the outer eval gets free source.
Sequencing without commas:  ((setup)>(g)) * f"..."   (setup runs, True keeps the string)
"""
import sys

WL = 'gctf{"*+*(=>:/)*+*}'
ATOMS = [('tt', 64), ('cc', 32), ('gg', 16), ('f', 8), ('t', 4), ('c', 2), ('g', 1)]
SETUP = '(tt:=(cc:=(gg:=(f:=(t:=(c:=(g:="g">"c")+g)+c)+t)+f)+gg)+cc)'


def num(n):
    parts = []
    for name, val in ATOMS:
        while n >= val:
            parts.append(name)
            n -= val
    assert n == 0
    return '+'.join(parts)


